var i=`1409-sapasui`;var e=`world-1409`;var o=`WS`;var s=`oceania`;var t=4;var r=39;var l={en:`Sapasui`,ua:`Сапасуї`};var g={en:`Samoan sapasui, a savory glass-noodle dish with meat, soy and vegetables, adapted for home cooking.`,ua:`Самоанський сапасуї, ситна страва зі скляної локшини, м’яса, соєвого соусу та овочів.`};var u=[{en:`Soak glass noodles in warm water until flexible, about 12 minutes; drain and snip into manageable lengths.`,ua:`Замочіть скляну локшину в теплій воді до гнучкості приблизно на 12 хвилин; відцідіть і розріжте на зручні шматки.`,t:[`soaking-dried-produce`,`draining`],m:12,i:[[`glass-noodles`,260,`g`],[`water`,700,`ml`]]},{en:`Heat oil and brown ground beef until no pink remains; stir in onion, ginger and garlic, and sauté until aromatic.`,ua:`Нагрійте олію й обсмажте яловичий фарш до повної готовності; додайте цибулю, імбир і часник та смажте до появи аромату.`,t:[`stir-frying`],m:10,i:[[`ground-beef`,400,`g`],[`vegetable-oil-neutral`,25,`ml`],[`yellow-onion`,120,`g`],[`ginger-root`,20,`g`],[`garlic`,3,`clove`]]},{en:`Add thinly cut cabbage and carrot; stir-fry for 5 minutes.`,ua:`Додайте тонко нашатковану капусту та моркву; смажте, помішуючи, 5 хвилин.`,t:[`stir-frying`],m:5,i:[[`white-cabbage`,180,`g`],[`carrot`,120,`g`]]},{en:`Add noodles, soy sauces and water. Simmer while turning until noodles absorb most liquid and turn translucent, about 10 minutes.`,ua:`Додайте локшину, соєві соуси та воду. Тушкуйте, обережно перевертаючи, поки локшина не вбере більшість рідини й стане прозорою, приблизно 10 хвилин.`,t:[`simmering`],m:10,i:[[`light-soy-sauce`,80,`ml`],[`dark-soy-sauce`,25,`ml`],[`water`,170,`ml`]]},{en:`Fold in sliced spring onions and serve hot.`,ua:`Вмішайте нарізану зелену цибулю й подавайте гарячим.`,t:[`garnishing`],m:2,i:[[`spring-onion`,40,`g`]]}];var d={slug:i,id:e,country:`WS`,region:s,servings:4,minutes:39,title:l,text:g,steps:u};export{o as country,d as default,e as id,r as minutes,s as region,t as servings,i as slug,u as steps,g as text,l as title};